//! 🧪️ Original terminal authority and ledger close separately with unchanged bounded policy.
use super::*;
use semio_framework_test_fixtures::fixture_text;
use semio_framework_trace::record_operation_started;
#[repr(transparent)]
struct TerminalJob<const N:usize>([u8;N]);

fn prepare_terminal_session<const N:usize>(params:BatchJobParams,caller:&mut OriginalJobFixtureCaller)->WorkerJobSession<TerminalJob<N>>{admit_original_fixture_owner!(caller,WorkerJobSession,TerminalJob([7u8;N]),params)}
impl<const N:usize> InteractiveJob for TerminalJob<N>{
 fn step<'a>(&'a mut self,cx:&mut StepContext<'_>,_:&mut OriginalJobReturnClaim<'_>)->InteractiveJobStep<'a>{InteractiveJobStep::from_callback(JobOutcomeBorrow::admit_yield(cx).map_err(OriginalTurnFailure::from))}fn borrow_outcome<'a>(&'a self,descriptor:&'a JobOutcomeDescriptor)->Result<JobOutcomeView<'a>,ValueError>{match descriptor.kind(){JobOutcomeKind::Yield=>descriptor.yielded(),JobOutcomeKind::Cancelled=>descriptor.cancelled(),_=>Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"fixture requires original yielded descriptor"))}}
 fn begin_close(&mut self){}
 fn close_step(&mut self,_:&mut StepContext<'_>)->Result<InteractiveJobCloseStep,OriginalTurnFailure>{Ok(InteractiveJobCloseStep::Complete{progress:Default::default()})}
 fn terminal_is_empty(&self)->bool{true}
}
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
#[test]
fn worker_terminal_session_retirement_preserves_original_arc_aliases_and_funded_scaffolds(){
 let(_,shared_trace)=observe(||record_operation_started(OperationId(99219),Generation(12)));
 let _admission=worker_session_slots_shared();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:65536,maximum_release_bytes:262144,maximum_depth:64};
 for aliases in [0,1,3]{let mut caller=OriginalJobFixtureCaller::admit(OperationId(99220),Generation(12),WORKER_TEST_STOCK,logical_now_us,u64::MAX,20000);let cancel=caller.admit_alias(grant);let(mut session,birth)=observe(||{let params=BatchJobParams{operation:OperationId(99220),generation:Generation(12),cancel,config:BatchDriveConfig{retained:grant,site:"test.original-session",stage:InteractiveStage::InteractiveStep,fuel_per_step:1,step_budget_us:1000},now_us:logical_now_us};prepare_terminal_session::<8192>(params,&mut caller)});let pointer=std::ptr::from_ref(&**session.inner);let mut original_aliases:[Option<session_return::SessionHandle<TerminalJob<8192>>>;3]=std::array::from_fn(|index|(index<aliases).then(||session.inner.0.as_ref().unwrap().clone()));session.begin_close();let mut released=0;let mut turns=0;
 while session.close_phase()!=WorkerJobClosePhase::SessionArc{turns+=1;assert!(turns<512);let(step,heap)=observe(||{if session.has_original_cancel_alias_witness(caller.cancel()).unwrap_or(false){let step=caller.turn(grant,|cx|{let turn=cx.with_original_effect(cx.retained_grant(),|cx,effect|session.return_original_cancel_alias_step(cx.original_cancel_token(),effect))?.map_or(semio_framework_value::RetainedWorkOutcome{result:Ok(None),work:0},|(turn,_)|turn);let result=turn.result.map(|step|step.expect("same original witnessed cancellation alias")).map_err(|error|match error{WorkerJobDemandError::Refused(error)=>error,WorkerJobDemandError::Contention(_)=>ValueError::literal(ValueRefusalKind::UnsupportedOwner,"original authority fixture alias remains checked out")});let step=receive_original_retained_work(cx,semio_framework_value::RetainedWorkOutcome{result,work:turn.work})?;Ok(step)}).unwrap();WorkerJobCloseStep::Pending{progress:step.progress()}}else{caller.turn(grant,|cx|session.close_step(cx)).unwrap()}});assert!(step.progress().fits(grant));assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),heap);released+=heap.1;assert_eq!(std::ptr::from_ref(&**session.inner),pointer);}
 let(demand,heap)=observe(||session.retirement_demands(grant.maximum_copy_bytes).unwrap());assert_eq!(heap,(0,0));assert_eq!(demand,session.original_session_arc_demands(grant.maximum_copy_bytes).unwrap());assert!(demand.copy_bytes<=4096);
 for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes.saturating_sub(1),..grant},RetainedCloneGrant{maximum_release_bytes:demand.release_bytes-1,..grant},RetainedCloneGrant{maximum_depth:0,..grant}].into_iter().filter(|denied|denied.maximum_items==0||denied.maximum_copy_bytes<demand.copy_bytes||denied.maximum_release_bytes<demand.release_bytes||denied.maximum_depth<demand.depth){let(step,heap)=observe(||caller.turn(denied,|cx|session.close_step(cx)).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(std::ptr::from_ref(&**session.inner),pointer);assert!(!session.terminal_is_empty());}
 if aliases>0{let(step,heap)=observe(||{if session.has_original_cancel_alias_witness(caller.cancel()).unwrap_or(false){let step=caller.turn(grant,|cx|{let turn=cx.with_original_effect(cx.retained_grant(),|cx,effect|session.return_original_cancel_alias_step(cx.original_cancel_token(),effect))?.map_or(semio_framework_value::RetainedWorkOutcome{result:Ok(None),work:0},|(turn,_)|turn);let result=turn.result.map(|step|step.expect("same original witnessed cancellation alias")).map_err(|error|match error{WorkerJobDemandError::Refused(error)=>error,WorkerJobDemandError::Contention(_)=>ValueError::literal(ValueRefusalKind::UnsupportedOwner,"original authority fixture alias remains checked out")});let step=receive_original_retained_work(cx,semio_framework_value::RetainedWorkOutcome{result,work:turn.work})?;Ok(step)}).unwrap();WorkerJobCloseStep::Pending{progress:step.progress()}}else{caller.turn(grant,|cx|session.close_step(cx)).unwrap()}});assert_eq!(step,WorkerJobCloseStep::Blocked);assert_eq!(heap,(0,0));assert_eq!(std::ptr::from_ref(&**session.inner),pointer);let(_,heap)=observe(||for original in &mut original_aliases{drop(original.take());});assert_eq!(heap,(0,0));}
 let(step,heap)=observe(||{if session.has_original_cancel_alias_witness(caller.cancel()).unwrap_or(false){let step=caller.turn(grant,|cx|{let turn=cx.with_original_effect(cx.retained_grant(),|cx,effect|session.return_original_cancel_alias_step(cx.original_cancel_token(),effect))?.map_or(semio_framework_value::RetainedWorkOutcome{result:Ok(None),work:0},|(turn,_)|turn);let result=turn.result.map(|step|step.expect("same original witnessed cancellation alias")).map_err(|error|match error{WorkerJobDemandError::Refused(error)=>error,WorkerJobDemandError::Contention(_)=>ValueError::literal(ValueRefusalKind::UnsupportedOwner,"original authority fixture alias remains checked out")});let step=receive_original_retained_work(cx,semio_framework_value::RetainedWorkOutcome{result,work:turn.work})?;Ok(step)}).unwrap();WorkerJobCloseStep::Pending{progress:step.progress()}}else{caller.turn(grant,|cx|session.close_step(cx)).unwrap()}});assert!(matches!(step,WorkerJobCloseStep::Pending{..}));assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),heap);assert_eq!(heap,(0,demand.release_bytes));released+=heap.1;assert!(session.inner.0.is_none());assert_eq!(session.generation(),Generation(12));assert_eq!(session.close_phase(),WorkerJobClosePhase::RetirementSlot);assert!(!session.terminal_is_empty());
 let(demand,heap)=observe(||session.retirement_demands(grant.maximum_copy_bytes).unwrap());assert_eq!(heap,(0,0));assert_eq!(demand.release_bytes,size_of::<WorkerJobRetirementNode<TerminalJob<8192>>>());let(step,heap)=observe(||{if session.has_original_cancel_alias_witness(caller.cancel()).unwrap_or(false){let step=caller.turn(grant,|cx|{let turn=cx.with_original_effect(cx.retained_grant(),|cx,effect|session.return_original_cancel_alias_step(cx.original_cancel_token(),effect))?.map_or(semio_framework_value::RetainedWorkOutcome{result:Ok(None),work:0},|(turn,_)|turn);let result=turn.result.map(|step|step.expect("same original witnessed cancellation alias")).map_err(|error|match error{WorkerJobDemandError::Refused(error)=>error,WorkerJobDemandError::Contention(_)=>ValueError::literal(ValueRefusalKind::UnsupportedOwner,"original authority fixture alias remains checked out")});let step=receive_original_retained_work(cx,semio_framework_value::RetainedWorkOutcome{result,work:turn.work})?;Ok(step)}).unwrap();WorkerJobCloseStep::Pending{progress:step.progress()}}else{caller.turn(grant,|cx|session.close_step(cx)).unwrap()}});assert!(matches!(step,WorkerJobCloseStep::Complete{..}));assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),heap);released+=heap.1;assert!(session.terminal_is_empty());assert_eq!(released,birth.0-birth.1);let(_,heap)=observe(||drop(session));assert_eq!(heap,(0,0));caller.retire(grant);
 }
}

